import{_ as l,a0 as r,w as s,s as d,ao as p,I as t,a1 as a,A as o,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在基於RedHat或Debian的系統上安裝 Wine 1.7 | LCTT x X-CMD","titleTemplate":false,"description":"在基於RedHat或Debian的系統上安裝 Wine 1.7 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在基於RedHat或Debian的系統上安裝 Wine 1.7 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在基於RedHat或Debian的系統上安裝 Wine 1.7 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140702 Wine 1.7.21 (Development Version) Released--Install in RedHat and Debian Based Systems","title":"在基於RedHat或Debian的系統上安裝 Wine 1.7","tag":"201408","desc":""},"relativePath":"201408/20140702 Wine 1.7.21 (Development Version) Released--Install in RedHat and Debian Based Systems.md","filePath":"[post].md"}'),u={name:"201408/20140702 Wine 1.7.21 (Development Version) Released--Install in RedHat and Debian Based Systems.md"};function m(w,e,b,g,f,x){const i=r("Link");return s(),d("div",null,[e[14]||(e[14]=p(`<h1 id="在基於redhat或debian的系統上安裝-wine-1-7" tabindex="-1">在基於RedHat或Debian的系統上安裝 Wine 1.7 <a class="header-anchor" href="#在基於redhat或debian的系統上安裝-wine-1-7" aria-label="Permalink to “在基於RedHat或Debian的系統上安裝 Wine 1.7”">​</a></h1><p>Wine,Linux上最流行也是最有力的軟件, 可以順利地在Linux平台上運行Windows程序和遊戲。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/05/Install-Wine-Development-Version.png" alt="安裝Wine "></p><p>這篇文章教你怎麼在像CentOS, Fedora, Ubuntu, Linux Mint一樣基於<strong>Red Hat</strong>和<strong>Debian</strong>的系統上安裝最新的<strong>Wine 1.7</strong>。</p><h3 id="在linux安裝-wine-1-7" tabindex="-1">在Linux安裝 Wine 1.7 <a class="header-anchor" href="#在linux安裝-wine-1-7" aria-label="Permalink to “在Linux安裝 Wine 1.7”">​</a></h3><p>不幸的, 在基於<strong>Red Hat</strong>的系統上沒有官方的 Wine 倉庫，所以唯一的安裝方式是從源碼編譯。你需要安裝一些依賴的包比如gcc, flex, bison, libX11-devel freetype-devel 和 Development Tools，這些包用來從源碼編譯Wine。我們可以用<strong>yum</strong>命令安裝他們。</p><h4 id="在-redhat-fedora-和-centos-上" tabindex="-1">在 RedHat, Fedora 和 CentOS 上 <a class="header-anchor" href="#在-redhat-fedora-和-centos-上" aria-label="Permalink to “在 RedHat, Fedora 和 CentOS 上”">​</a></h4><pre><code># yum -y groupinstall &#39;Development Tools&#39;
# yum -y install flex bison libX11-devel freetype-devel
</code></pre><p>接下來，下載最新的開發版本(如<strong>1.7.21</strong>)並用下面的命令解壓。</p><pre><code>$ cd /tmp
$ wget http://citylan.dl.sourceforge.net/project/wine/Source/wine-1.7.21.tar.bz2
$ tar -xvf wine-1.7.21.tar.bz2 -C /tmp/
</code></pre><p>現在，要以普通用户身份編譯並搭建Wine的安裝程序。(<strong>注意</strong>: 根據機器性能和網絡速度的不同，安裝過程需要 <strong>15-20</strong> 分鐘，安裝過程中會要求輸入 <strong>root</strong> 密碼。)</p><p><strong>32位系統上</strong></p><pre><code>$ cd wine-1.7.21/
$ ./tools/wineinstall
</code></pre><p><strong>64位系統上</strong></p><pre><code>$ cd wine-1.7.21/
$ ./configure --enable-win64
$ make
# make install
</code></pre><h4 id="在ubuntu-debian-和-linux-mint-上" tabindex="-1">在Ubuntu, Debian 和 Linux Mint 上 <a class="header-anchor" href="#在ubuntu-debian-和-linux-mint-上" aria-label="Permalink to “在Ubuntu, Debian 和 Linux Mint 上”">​</a></h4><p>在基於<strong>Ubuntu</strong> 的系統上, 你可以用官方的 <strong>PPA</strong>來輕鬆安裝最新的Wine。打開一個新終端用sudo運行如下命令。</p><pre><code>$ sudo add-apt-repository ppa:ubuntu-wine/ppa 
$ sudo apt-get update
$ sudo apt-get install wine 1.7 winetricks
</code></pre><p>一旦裝完了，你可以以如下方式運行基於Windows的軟件和遊戲。</p><pre><code>$ wine notepad
$ wine notepad.exe 
$ wine c:\\\\windows\\\\notepad.exe
</code></pre><p><strong>注意</strong>: 請記住，如果是開發版本不要用在生產環境。 建議只用在測試用途</p><p>如果你想安裝最近的穩定版Wine, 請看下面的文章, 在文章裏介紹了在幾乎所以Linux系統中安裝Wine的方法</p>`,22)),t("ul",null,[t("li",null,[a(i,{href:"http://www.tecmint.com/install-wine-in-rhel-centos-and-fedora/"},{default:o(()=>[...e[0]||(e[0]=[n("Install Wine 1.6.2 (Stable) in RHEL, CentOS and Fedora",-1)])]),_:1})]),t("li",null,[a(i,{href:"http://www.tecmint.com/install-wine-on-ubuntu-and-linux-mint/"},{default:o(()=>[...e[1]||(e[1]=[n("Install Wine 1.6.2 (Stable) in Debian, Ubuntu and Mint",-1)])]),_:1})])]),e[15]||(e[15]=t("h3",{id:"參考鏈接",tabindex:"-1"},[n("參考鏈接 "),t("a",{class:"header-anchor",href:"#參考鏈接","aria-label":"Permalink to “參考鏈接”"},"​")],-1)),t("ul",null,[t("li",null,[a(i,{href:"http://www.winehq.org/"},{default:o(()=>[...e[2]||(e[2]=[n("WineHQ Homepage",-1)])]),_:1})])]),e[16]||(e[16]=t("hr",null,null,-1)),t("p",null,[e[4]||(e[4]=n("via: ",-1)),a(i,{href:"http://www.tecmint.com/install-wine-in-linux/"},{default:o(()=>[...e[3]||(e[3]=[n("http://www.tecmint.com/install-wine-in-linux/",-1)])]),_:1})]),t("p",null,[e[7]||(e[7]=n("譯者：",-1)),a(i,{href:"https://github.com/2q1w2007"},{default:o(()=>[...e[5]||(e[5]=[n("2q1w2007",-1)])]),_:1}),e[8]||(e[8]=n(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[6]||(e[6]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=n("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[9]||(e[9]=[n("LCTT",-1)])]),_:1}),e[12]||(e[12]=n(" 原創翻譯，",-1)),a(i,{href:"http://linux.cn/"},{default:o(()=>[...e[10]||(e[10]=[n("Linux中國",-1)])]),_:1}),e[13]||(e[13]=n(" 榮譽推出",-1))])])}const T=l(u,[["render",m]]);export{h as __pageData,T as default};
